1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type QuoteResult = { premium: number };
36	export type ClaimResult = { payout: number; remainingCap: number };
37	export type StepResult = QuoteResult | ClaimResult;
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	const PROCESSING_FEE = 5;
44	const FIRST_INSURANCE_SURCHARGE = 0.1;
45	
46	const BASE_PREMIUMS = {
47	  sword: 100,
48	  amulet: 60,
49	  staff: 80,
50	  potion: 40,
51	  rune: 25,
52	  moonstone: 25,
53	} as const satisfies Record<string, number>;
54	
55	type KnownItemType = keyof typeof BASE_PREMIUMS;
56	
57	const basePremiumOf = (itemType: string): number => BASE_PREMIUMS[itemType as KnownItemType];
58	
59	const BLOCK_SIZE = 3;
60	const BLOCK_PREMIUM = 60;
61	
62	const countsByType = (items: Item[]): Map<string, number> => {
63	  const counts = new Map<string, number>();
64	  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
65	  return counts;
66	};
67	
68	const basePremiumForGroup = (itemType: string, count: number): number => {
69	  if (count === BLOCK_SIZE) return BLOCK_PREMIUM;
70	  return count * basePremiumOf(itemType);
71	};
72	
73	const policyBasePremiumOf = (items: Item[]): number =>
74	  [...countsByType(items)].reduce(
75	    (total, [itemType, count]) => total + basePremiumForGroup(itemType, count),
76	    0,
77	  );
78	
79	const CURSE_SURCHARGE = 0.5;
80	
81	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
82	const HIGH_ENCHANTMENT_THRESHOLD = 5;
83	
84	const itemSurchargeRateOf = (item: Item): number => {
85	  const curse = item.cursed ? CURSE_SURCHARGE : 0;
86	  const enchantment =
87	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD ? HIGH_ENCHANTMENT_SURCHARGE : 0;
88	  return curse + enchantment;
89	};
90	
91	const itemSurchargesOf = (items: Item[]): number =>
92	  items.reduce((total, item) => total + basePremiumOf(item.type) * itemSurchargeRateOf(item), 0);
93	
94	const LOYALTY_DISCOUNT = 0.2;
95	const LOYALTY_THRESHOLD_YEARS = 2;
96	
97	const loyaltyRateOf = (customer: Customer): number =>
98	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? -LOYALTY_DISCOUNT : 0;
99	
100	const FOLLOW_UP_DISCOUNT = 0.15;
101	
102	// `contractOrdinal` is zero-based: the customer's first contract in the
103	// scenario is 0 and carries no follow-up discount.
104	const followUpRateOf = (contractOrdinal: number): number =>
105	  contractOrdinal > 0 ? -FOLLOW_UP_DISCOUNT : 0;
106	
107	// The policy-scoped rate is the sum of every modifier that scales the policy
108	// base premium. Each addend names one rule from the spec.
109	const policyModifierRateOf = (customer: Customer, contractOrdinal: number): number =>
110	  FIRST_INSURANCE_SURCHARGE + loyaltyRateOf(customer) + followUpRateOf(contractOrdinal);
111	
112	const premiumFor = (quote: QuoteStep, customer: Customer, contractOrdinal: number): number => {
113	  const policyBase = policyBasePremiumOf(quote.items);
114	  // Policy-scoped modifiers apply to the policy base only; item-scoped
115	  // surcharges are added afterwards and never widen that base.
116	  const policyModifiers = policyBase * policyModifierRateOf(customer, contractOrdinal);
117	  return Math.ceil(
118	    policyBase + itemSurchargesOf(quote.items) + policyModifiers + PROCESSING_FEE,
119	  );
120	};
121	
122	const INSURANCE_VALUES = {
123	  sword: 1000,
124	  amulet: 600,
125	  staff: 800,
126	  potion: 400,
127	  rune: 250,
128	  moonstone: 250,
129	} as const satisfies Record<string, number>;
130	
131	const insuranceValueOf = (itemType: string): number =>
132	  INSURANCE_VALUES[itemType as KnownItemType];
133	
134	const DEDUCTIBLE = 100;
135	const CAP_MULTIPLE = 2;
136	
137	interface Policy {
138	  items: Item[];
139	  remainingCap: number;
140	}
141	
142	const openPolicy = (items: Item[]): Policy => {
143	  const insuranceSum = items.reduce((sum, item) => sum + insuranceValueOf(item.type), 0);
144	  return { items, remainingCap: insuranceSum * CAP_MULTIPLE };
145	};
146	
147	const FULL_REIMBURSEMENT = 1;
148	const HALVED_REIMBURSEMENT = 0.5;
149	// Distinct from HIGH_ENCHANTMENT_THRESHOLD (5), which drives the *premium*
150	// surcharge. Enchantment 5–7 costs more to insure but is still reimbursed in
151	// full; only from 8 up is the payout halved.
152	const HALVED_REIMBURSEMENT_THRESHOLD = 8;
153	
154	const reimbursementRateOf = (item: Item): number =>
155	  (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_THRESHOLD
156	    ? HALVED_REIMBURSEMENT
157	    : FULL_REIMBURSEMENT;
158	
159	// The deductible is withheld once per damage entry, not once per claim.
160	const payoutForDamage = (damage: Damage, item: Item): number =>
161	  damage.amount * reimbursementRateOf(item) - DEDUCTIBLE;
162	
163	// The insured item a damage entry refers to. The non-null assertion is a
164	// deliberate placeholder: "damage entry not covered by the policy" is a
165	// pending error test.
166	const insuredItemFor = (damage: Damage, policy: Policy): Item =>
167	  policy.items.find((item) => item.type === damage.itemType)!;
168	
169	const settle = (claim: ClaimStep, policy: Policy): ClaimResult => {
170	  const owed = claim.incident.damages.reduce(
171	    (total, damage) => total + payoutForDamage(damage, insuredItemFor(damage, policy)),
172	    0,
173	  );
174	  // Rounded down in the MHPCO's favour, then the cap is drawn down by what
175	  // was actually paid — so the remaining cap stays whole.
176	  const payout = Math.floor(owed);
177	  policy.remainingCap -= payout;
178	  return { payout, remainingCap: policy.remainingCap };
179	};
180	
181	export const runScenario = (scenario: Scenario): ScenarioResult => {
182	  // Counts the quote steps seen so far. Only quotes open a contract, so this
183	  // deliberately tracks the customer's contracts rather than the step index —
184	  // a claim step between two quotes must not advance the ordinal.
185	  let contractsSoFar = 0;
186	  const policies = new Map<number, Policy>();
187	
188	  const resultOf = (step: Step, index: number): StepResult => {
189	    if (step.op === "claim") {
190	      const policy = policies.get(step.policy)!;
191	      return settle(step, policy);
192	    }
193	    const premium = premiumFor(step, scenario.customer, contractsSoFar);
194	    contractsSoFar += 1;
195	    policies.set(index, openPolicy(step.items));
196	    return { premium };
197	  };
198	
199	  return { results: scenario.steps.map(resultOf) };
200	};
